input.sparql:
SELECT ?z ?type ?label WHERE {
  ?z a brick:HVAC_Zone.
  FILTER(str(?z) LIKE "%ZN_6%")
  OPTIONAL { ?z rdfs:label ?label }
  OPTIONAL { ?z a ?type }
}

SELECT ?z ?type ?label WHERE {
  ?z a brick:HVAC_Zone.
  FILTER(str(?z) LIKE "%ZN_6%")
  OPTIONAL { ?z rdfs:label ?label }
}

SELECT ?z ?label ?ts WHERE {
  ?z a brick:HVAC_Zone.
  FILTER(str(?z) LIKE "%ZN_6%")
  ?z ref:hasExternalReference ?ref .
  ?ref ref:hasTimeseriesId ?ts .
  OPTIONAL { ?z rdfs:label ?label }
}

SELECT ?sensor ?ts ?point WHERE {
  ?sensor rdfs:label ?lbl .
  ?sensor a brick:AirTemperatureSensor .
  ?sensor brick:hasMeasurement ?point .
  ?sensor brick:locationInFloor ?fl .
  {
    ?x rdfs:label "DataCenter_mid_ZN_6" .
    ?x a brick:HVAC_Zone .
  }
}

SELECT ?sensor ?ts WHERE {
  ?sensor a brick:AirTemperatureSensor .
  ?sensor ref:hasExternalReference ?ref .
  ?ref ref:hasTimeseriesId ?ts .
}

SELECT (COUNT(?s)) ?n ?s WHERE {
  ?s a brick:Sensor .
}
GROUP BY ?s

SELECT ?s ?ts WHERE {
  ?s a brick:Zone_Air_Temperature_Sensor .
  ?s ref:hasExternalReference ?ref .
  ?ref ref:hasTimeseriesId ?ts .
}
